<?php
$error=null;$role=role_name();$patientSelf=patient_for_current_user();$doctorSelf=doctor_for_current_user();
if(request_method('POST')){try{verify_csrf();$action=post_string('action');if($action==='book'){$patientId=$role==='Patient'?(int)($patientSelf['patient_id']??0):(int)($_POST['patient_id']??0);$doctorId=(int)($_POST['doctor_id']??0);$date=post_string('appointment_date');$start=post_string('start_time');$end=post_string('end_time');$reason=post_string('reason');if($patientId<1||$doctorId<1||!validate_date($date)||$date<date('Y-m-d')||$start===''||$end==='')throw new RuntimeException('Select a patient, doctor, date and available time slot.');$day=(int)date('w',strtotime($date));$activeDoctor=(int)query_value("SELECT COUNT(*) FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE d.doctor_id=? AND d.status='Active' AND u.account_status='Active'",[$doctorId]);if(!$activeDoctor)throw new RuntimeException('The selected doctor is not active.');$activePatient=(int)query_value("SELECT COUNT(*) FROM patients WHERE patient_id=? AND status='Active'",[$patientId]);if(!$activePatient)throw new RuntimeException('The selected patient is not active.');$exceptionStmt=db()->prepare('SELECT * FROM schedule_exceptions WHERE doctor_id=? AND exception_date=? LIMIT 1');$exceptionStmt->execute([$doctorId,$date]);$exception=$exceptionStmt->fetch();if($exception&&$exception['exception_type']==='Unavailable')throw new RuntimeException('The doctor is unavailable on this date.');$stmt=db()->prepare("SELECT * FROM doctor_schedules WHERE doctor_id=? AND day_of_week=? AND status='Active' ORDER BY start_time");$stmt->execute([$doctorId,$day]);$schedules=$stmt->fetchAll();if(!$schedules)throw new RuntimeException('The doctor has no active schedule on this date.');if($exception&&$exception['exception_type']==='Alternative Hours'){if(!$exception['alternative_start_time']||!$exception['alternative_end_time']||$exception['alternative_start_time']>=$exception['alternative_end_time'])throw new RuntimeException('Alternative hours are not configured correctly.');$alternative=$schedules[0];$alternative['start_time']=$exception['alternative_start_time'];$alternative['end_time']=$exception['alternative_end_time'];$schedules=[$alternative];}$selectedStart=strtotime($date.' '.$start);$selectedEnd=strtotime($date.' '.$end);if($selectedStart===false||$selectedEnd===false||$selectedEnd<=$selectedStart)throw new RuntimeException('The selected appointment time is invalid.');if($date===date('Y-m-d')&&$selectedStart<=time())throw new RuntimeException('Choose a future time slot.');$validSlot=false;foreach($schedules as $schedule){$scheduleStart=strtotime($date.' '.$schedule['start_time']);$scheduleEnd=strtotime($date.' '.$schedule['end_time']);$slotMinutes=max(1,(int)$schedule['slot_duration']);$expectedEnd=$selectedStart+($slotMinutes*60);$offsetMinutes=(int)(($selectedStart-$scheduleStart)/60);$slotIndex=$offsetMinutes>=0?intdiv($offsetMinutes,$slotMinutes):-1;if($selectedStart>=$scheduleStart&&$selectedEnd===$expectedEnd&&$selectedEnd<=$scheduleEnd&&$offsetMinutes%$slotMinutes===0&&$slotIndex<(int)$schedule['maximum_patients']){$validSlot=true;break;}}if(!$validSlot)throw new RuntimeException('The selected time is not a valid appointment slot.');$pdo=db();$pdo->beginTransaction();$stmt=$pdo->prepare("SELECT appointment_id FROM appointments WHERE doctor_id=? AND appointment_date=? AND start_time=? AND status NOT IN ('Cancelled','No-show') FOR UPDATE");$stmt->execute([$doctorId,$date,$start]);if($stmt->fetch())throw new RuntimeException('That time slot was just booked. Please select another slot.');$stmt=$pdo->prepare("SELECT appointment_id FROM appointments WHERE patient_id=? AND appointment_date=? AND start_time=? AND status NOT IN ('Cancelled','No-show') FOR UPDATE");$stmt->execute([$patientId,$date,$start]);if($stmt->fetch())throw new RuntimeException('The patient already has an appointment at that time.');$stmt=$pdo->prepare("INSERT INTO appointments (patient_id,doctor_id,appointment_date,start_time,end_time,reason,booking_source,appointment_type,status,booked_by) VALUES (?,?,?,?,?,?,?,?,?,?)");$source=$role==='Patient'?'Portal':'Reception';$status=$role==='Patient'?'Pending':'Confirmed';$stmt->execute([$patientId,$doctorId,$date,$start,$end,nullable($reason),$source,post_string('appointment_type','Regular'),$status,current_user()['user_id']]);$id=(int)$pdo->lastInsertId();$number=appointment_code($id);$pdo->prepare('UPDATE appointments SET appointment_number=? WHERE appointment_id=?')->execute([$number,$id]);$fee=(float)query_value('SELECT consultation_fee FROM doctors WHERE doctor_id=?',[$doctorId]);$pdo->prepare('INSERT INTO invoices (patient_id,appointment_id,created_by) VALUES (?,?,?)')->execute([$patientId,$id,current_user()['user_id']]);$invoiceId=(int)$pdo->lastInsertId();$invNumber=invoice_code($invoiceId);$pdo->prepare('UPDATE invoices SET invoice_number=? WHERE invoice_id=?')->execute([$invNumber,$invoiceId]);$pdo->prepare('INSERT INTO invoice_items (invoice_id,item_type,reference_id,description,quantity,unit_price,line_total) VALUES (?,\'Consultation\',?,\'Doctor consultation fee\',1,?,?)')->execute([$invoiceId,$doctorId,$fee,$fee]);recalculate_invoice($invoiceId);$pdo->commit();notify_user(find_patient_user_id($patientId),'Appointment booked',$number.' is scheduled for '.format_date($date).' at '.format_time($start),'Appointment','appointments',$id);notify_user(find_doctor_user_id($doctorId),'New appointment',$number.' has been added to your schedule.','Appointment','appointments',$id);log_action('BOOK','appointments',$id,null,['number'=>$number]);flash('appointment','Appointment booked successfully.','success');redirect_to('appointments');}
if($action==='status'){$id=(int)($_POST['appointment_id']??0);$new=post_string('new_status');$allowed=['Confirmed','Cancelled','No-show'];$pdo=db();$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT * FROM appointments WHERE appointment_id=? FOR UPDATE');$stmt->execute([$id]);$app=$stmt->fetch();if(!$app)throw new RuntimeException('Appointment not found.');if($role==='Patient'){if((int)$app['patient_id']!==(int)$patientSelf['patient_id']||$new!=='Cancelled'||!in_array($app['status'],['Pending','Confirmed'],true))throw new RuntimeException('You cannot update this appointment.');$noticeHours=max(0,(int)setting('appointment_cancellation_hours',4));$appointmentTimestamp=strtotime($app['appointment_date'].' '.$app['start_time']);if($noticeHours>0&&$appointmentTimestamp!==false&&$appointmentTimestamp-time()<$noticeHours*3600)throw new RuntimeException('Online cancellation closes '.$noticeHours.' hours before the appointment. Contact reception for help.');}elseif(!has_role(['Admin','Receptionist']))throw new RuntimeException('You cannot update appointment status here.');if(!in_array($new,$allowed,true))throw new RuntimeException('Invalid appointment status.');$transitions=['Pending'=>['Confirmed','Cancelled','No-show'],'Confirmed'=>['Cancelled','No-show'],'Checked In'=>['No-show'],'Waiting'=>['No-show']];if(!in_array($new,$transitions[$app['status']]??[],true))throw new RuntimeException('This appointment can no longer be changed to '.$new.'.');if($new==='No-show'&&$app['appointment_date']>date('Y-m-d'))throw new RuntimeException('A future appointment cannot be marked as no-show.');$cancelReason=$new==='Cancelled'?post_string('cancellation_reason'):null;$pdo->prepare('UPDATE appointments SET status=?,cancellation_reason=?,cancelled_at=? WHERE appointment_id=?')->execute([$new,$cancelReason,$new==='Cancelled'?date('Y-m-d H:i:s'):null,$id]);if($new==='Cancelled')$pdo->prepare("UPDATE invoices SET status='Void',payment_status='Cancelled',due_amount=0 WHERE appointment_id=? AND paid_amount=0")->execute([$id]);if($new==='No-show')$pdo->prepare("UPDATE queue_tokens SET queue_status='No-show' WHERE appointment_id=?")->execute([$id]);$pdo->commit();notify_user(find_patient_user_id((int)$app['patient_id']),'Appointment updated',$app['appointment_number'].' status changed to '.$new,'Appointment','appointments',$id);log_action('STATUS_CHANGE','appointments',$id,['status'=>$app['status']],['status'=>$new]);flash('appointment','Appointment status updated.','success');redirect_to('appointments');}}
catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$departments=db()->query("SELECT * FROM departments WHERE status='Active' ORDER BY department_name")->fetchAll();$patients=[];if(has_role(['Admin','Receptionist']))$patients=db()->query("SELECT patient_id,patient_code,full_name,phone FROM patients WHERE status='Active' ORDER BY full_name LIMIT 500")->fetchAll();
$where=[];$params=[];if($role==='Patient'){$where[]='a.patient_id=?';$params[]=$patientSelf['patient_id'];}elseif($role==='Doctor'){$where[]='a.doctor_id=?';$params[]=$doctorSelf['doctor_id'];}if(get_string('date')!==''){$where[]='a.appointment_date=?';$params[]=get_string('date');}if(get_string('status')!==''){$where[]='a.status=?';$params[]=get_string('status');}$sql="SELECT a.*,p.patient_code,p.full_name patient_name,p.phone patient_phone,u.full_name doctor_name,d.specialization,dep.department_name,q.token_number FROM appointments a JOIN patients p ON p.patient_id=a.patient_id JOIN doctors d ON d.doctor_id=a.doctor_id JOIN users u ON u.user_id=d.user_id JOIN departments dep ON dep.department_id=d.department_id LEFT JOIN queue_tokens q ON q.appointment_id=a.appointment_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY a.appointment_date DESC,a.start_time DESC LIMIT 200";$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$showForm=isset($_GET['new']);
?>
<div class="page-header"><div><h2>Appointments</h2><p>Book, confirm and track outpatient visits.</p></div><?php if(in_array($role,['Admin','Receptionist','Patient'],true)):?><button class="btn btn-primary" data-modal-open="appointmentModal">＋ Book appointment</button><?php endif;?></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card mb-2"><form method="get" class="actions"><input type="hidden" name="page" value="appointments"><input class="input" style="max-width:190px" type="date" name="date" value="<?=e(get_string('date'))?>"><select class="select" style="max-width:190px" name="status"><option value="">All statuses</option><?php foreach(['Pending','Confirmed','Checked In','Waiting','In Consultation','Completed','Cancelled','No-show'] as $s):?><option <?=get_string('status')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-light">Apply filters</button><a class="btn btn-light" href="<?=e(route_url('appointments'))?>">Reset</a></form></div>
<div class="card"><div class="card-header"><div><h3>Appointment records</h3><p><?=count($rows)?> records shown.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Appointment</th><th>Patient</th><th>Doctor</th><th>Date & time</th><th>Token</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="table-title"><?=e($r['appointment_number'])?></div><div class="table-subtitle"><?=e($r['booking_source'])?> · <?=e($r['appointment_type'])?></div></td><td><?=e($r['patient_name'])?><div class="table-subtitle"><?=e($r['patient_code'])?></div></td><td><?=e($r['doctor_name'])?><div class="table-subtitle"><?=e($r['department_name'])?></div></td><td><?=format_date($r['appointment_date'])?><div class="table-subtitle"><?=format_time($r['start_time'])?> – <?=format_time($r['end_time'])?></div></td><td><?=e($r['token_number']??'—')?></td><td><span class="badge badge-<?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><div class="actions"><?php if(has_role(['Admin','Receptionist'])&&$r['status']==='Pending'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="appointment_id" value="<?=$r['appointment_id']?>"><input type="hidden" name="new_status" value="Confirmed"><button class="btn btn-primary btn-sm">Confirm</button></form><?php endif;?><?php if((($role==='Patient'&&(int)$r['patient_id']===(int)$patientSelf['patient_id'])||has_role(['Admin','Receptionist']))&&in_array($r['status'],['Pending','Confirmed'],true)):?><form method="post" onsubmit="return confirm('Cancel this appointment?')"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="appointment_id" value="<?=$r['appointment_id']?>"><input type="hidden" name="new_status" value="Cancelled"><input type="hidden" name="cancellation_reason" value="Cancelled by user"><button class="btn btn-danger btn-sm">Cancel</button></form><?php endif;?><?php if(has_role(['Admin','Receptionist'])&&in_array($r['status'],['Confirmed','Checked In'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="appointment_id" value="<?=$r['appointment_id']?>"><input type="hidden" name="new_status" value="No-show"><button class="btn btn-warning btn-sm">No-show</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div>
<?php if(in_array($role,['Admin','Receptionist','Patient'],true)):?><div class="modal-backdrop <?=$showForm?'open':''?>" id="appointmentModal"><div class="modal"><div class="modal-header"><h3>Book appointment</h3><button class="close-btn" data-modal-close>×</button></div><form method="post" id="appointmentForm" data-api="<?=e(url('api.php'))?>"><div class="modal-body"><?=csrf_field()?><input type="hidden" name="action" value="book"><div class="stepper"><span class="step active"></span><span class="step active"></span><span class="step"></span><span class="step"></span><span class="step"></span></div><?php if($role!=='Patient'):?><div class="field"><label class="required">Patient</label><select class="select" name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['patient_id']?>"><?=e($p['patient_code'].' — '.$p['full_name'].' — '.$p['phone'])?></option><?php endforeach;?></select></div><?php endif;?><div class="form-grid"><div class="field"><label class="required">Department</label><select class="select" id="department_id" required><option value="">Select department</option><?php foreach($departments as $d):?><option value="<?=$d['department_id']?>"><?=e($d['department_name'])?></option><?php endforeach;?></select></div><div class="field"><label class="required">Doctor</label><select class="select" id="doctor_id" name="doctor_id" required><option value="">Select department first</option></select></div><div class="field"><label class="required">Date</label><input class="input" id="appointment_date" type="date" min="<?=date('Y-m-d')?>" name="appointment_date" required></div><div class="field"><label>Type</label><select class="select" name="appointment_type"><option>Regular</option><option>Follow-up</option><option>Emergency</option></select></div></div><div class="field"><label class="required">Available time</label><p class="help" id="slotMessage">Choose a doctor and date to see available slots.</p><di